data class SubjectPrincipal(val id: String, val roles: Set<String>) : Principal

install(Authentication) { bearer("api") { validate { call -> subjectFor(call) } } }

routing {
    authenticate("api") {
        get("/reports") {
            val who = call.principal<SubjectPrincipal>()!!   // null unless the provider ran
            call.respond(Reports.forRoles(who.roles))
        }
    }
}
